import { Injectable, Logger, LogLevel, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppConfigService } from '../app-config/app-config.service';

@Injectable()
export class LoggerConfigService implements OnModuleInit {
  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
  ) {}

  public async masterDiLogLevel(): Promise<LogLevel> {
    let value = this.configService.get<string>('masterDiLogLevel') as LogLevel;

    if (value) {
      Logger.warn(`'masterDiLogLevel' was read from environment variable`);
    } else {
      value = (await this.appConfigService.getConfigurationValue(
        'MASTER_DI_LOG_LEVEL',
      )) as LogLevel;
    }

    return value ?? '';
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      Logger.error(storeNotReachableMessage);
      throw new Error(storeNotReachableMessage);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [{ key: 'masterDiLogLevel', value: await this.masterDiLogLevel() }];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        Logger.error(`Missing configuration value for ${config.key}`);
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
  }
}

