import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
import { AppConfigModule } from '@/config/app-config/app-config.module';
import { RedisConfigService } from '@/config/redis/redis-sdk/redis-sdk.service';

@Module({
  exports: [RedisConfigService],
  imports: [ConfigModule, AppConfigModule],
  providers: [RedisConfigService],
})
export class RedisSdkCofigModule {}

import { DefaultAzureCredential } from '@azure/identity';
import { DaprClient } from '@dapr/dapr';
import { JobsLogContext, FullRedisConfig } from '@mesx/common-lib';
import { Injectable, OnModuleInit } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { AppLogger } from '@/common/logger/app-logger';
import { AppConfigService } from '@/config/app-config/app-config.service';

@Injectable()
export class RedisConfigService implements OnModuleInit, FullRedisConfig {
  private readonly context: JobsLogContext = {
    method: '',
    service: RedisConfigService.name,
  };

  public constructor(
    private readonly configService: ConfigService,
    private readonly appConfigService: AppConfigService,
    private readonly customLogger: AppLogger,
  ) {}

  public get redisHostManagedRedis(): string {
    return (
      this.configService.get<string>('redisHostManagedRedis') ?? 'localhost'
    );
  }

  public get redisPortManagedRedis(): number {
    return this.configService.get<number>('redisPortManagedRedis') ?? 10_000;
  }

  public get statePrefix(): string {
    return this.configService.get<string>('statePrefix') ?? '';
  }

  public get username(): string {
    return this.configService.get<string>('username') ?? '';
  }

  public get localRedisPassword(): string {
    return this.configService.get<string>('localRedisPassword') ?? '';
  }

  public get useTls(): boolean {
    return this.configService.get<boolean>('useTls') ?? false;
  }

  public get useRedisLocal(): boolean {
    return this.configService.get<boolean>('useRedisLocal') ?? false;
  }

  public get redisScope(): string {
    return (
      this.configService.get<string>('redisScope') ??
      'https://redis.azure.com/.default'
    );
  }

  public get daprSecretStore(): string {
    return this.configService.get<string>('mainSecretStore') ?? '';
  }

  public get mainAccessKeySecretName(): string {
    return this.configService.get<string>('mainAccessKeySecretName') ?? '';
  }

  public extractUsernameFromToken(token: string): string {
    const context: JobsLogContext = {
      method: 'extractUsernameFromToken',
      service: 'RedisConfigService',
    };
    this.customLogger.debug('Extraciting Username from token', context);
    const base64Metadata = token.split('.')[1];
    const { oid } = JSON.parse(
      Buffer.from(base64Metadata, 'base64').toString('utf8'),
    );
    this.customLogger.debug(`OID: ${oid}`, context);
    return oid;
  }

  public async getMainAccessKeySecretValue(
    client: DaprClient,
    store: string,
    name: string,
  ): Promise<string> {
    try {
      const secret = await client.secret.get(store, name);
      return Object.values(secret)[0];
    } catch (error) {
      this.customLogger.error(
        'Error while getting Main Access Key',
        this.context,
        error,
      );
      throw new Error('Failed to retrieve Main Access Key');
    }
  }

  public async dataIngestionWorkdataTtlSecondes(): Promise<number> {
    const context: JobsLogContext = {
      method: 'dataIngestionWorkdataTtlSecondes',
      service: 'RedisConfigService',
    };
    const ttlEnvironment = this.configService.get<string>(
      'dataIngestionWorkdataTtlSecondes',
    );

    if (ttlEnvironment === undefined) {
      const appStoreValue = Number(
        await this.appConfigService.getConfigurationValue(
          'MASTER_DATA_INGESTION_WORKDATA_TTL_SECONDS',
        ),
      );
      return Number.isNaN(appStoreValue) ? 7200 : appStoreValue ?? 7200;
    }
    const ttlValue = Number(ttlEnvironment);
    return Number.isNaN(ttlValue) ? 7200 : ttlValue ?? 7200;
  }

  public async getAzureTokenWithExpiry(): Promise<{
    token: string;
    expiresOn: Date;
  }> {
    const context: JobsLogContext = {
      method: 'getAzureTokenWithExpiry',
      service: 'RedisConfigService',
    };
    try {
      this.customLogger.debug('Getting Azure token with expiry', context);
      const credential = new DefaultAzureCredential();
      const tokenResponse = await credential.getToken(this.redisScope);
      return {
        expiresOn: tokenResponse.expiresOnTimestamp
          ? new Date(tokenResponse.expiresOnTimestamp)
          : new Date(Date.now() + 3600 * 1000),
        token: tokenResponse.token,
      };
    } catch (error) {
      this.customLogger.error(
        'Error while getting Azure token',
        context,
        error,
      );
      throw new Error('Failed to retrieve Azure token');
    }
  }

  public async onModuleInit(): Promise<void> {
    await this.checkConfiguration();
  }

  private async checkConfiguration(): Promise<void> {
    const context: JobsLogContext = {
      method: 'checkConfiguration',
      service: 'RedisConfigService',
    };
    if (!(await this.appConfigService.reachable())) {
      const storeNotReachableMessage = `App Configuration Store '${this.appConfigService.configStoreId}' is not reachable !`;

      this.customLogger.error(storeNotReachableMessage, context);
      throw new Error(storeNotReachableMessage);
    }

    const requiredConfigs: Array<{
      key: string;
      value: string | number | boolean | undefined;
    }> = [
      {
        key: 'dataIngestionWorkdataTtlSecondes',
        value: await this.dataIngestionWorkdataTtlSecondes(),
      },
      {
        key: 'statePrefix',
        value: this.statePrefix,
      },
      {
        key: 'mainSecretStore',
        value: this.daprSecretStore,
      },
      {
        key: 'mainAccessKeySecretName',
        value: this.mainAccessKeySecretName,
      },
      {
        key: 'redisHostManagedRedis',
        value: this.redisHostManagedRedis,
      },
      {
        key: 'redisPortManagedRedis',
        value: this.redisPortManagedRedis,
      },
    ];

    // Check mandatory fields
    for (const config of requiredConfigs) {
      if (config.value === undefined) {
        this.customLogger.error(
          `Missing configuration value for ${config.key}`,
          context,
        );
        throw new Error(`Configuration error: ${config.key} is not set`);
      }
    }
    const hasUsernameAndPassword = this.username && this.localRedisPassword;
    const hasManagedIdentity = await this.getAzureTokenWithExpiry();
    if (!hasUsernameAndPassword && !hasManagedIdentity.token) {
      this.customLogger.error(
        'Either username/password or useManagedIdentity must be provided',
        context,
      );
      throw new Error(
        'Configuration error: You must set either username/password or useManagedIdentity',
      );
    }
  }
}

